"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export default function SectionStory() {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      const words = textRef.current?.querySelectorAll(".word");
      if (words) {
        gsap.fromTo(
          words,
          { y: 80, opacity: 0 },
          {
            y: 0,
            opacity: 1,
            duration: 0.8,
            stagger: 0.06,
            ease: "power3.out",
            scrollTrigger: {
              trigger: containerRef.current,
              start: "top 75%",
              toggleActions: "play none none reverse",
            },
          }
        );
      }

      gsap.fromTo(
        ".story-paragraph",
        { y: 40, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 1,
          delay: 0.4,
          ease: "power3.out",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 70%",
            toggleActions: "play none none reverse",
          },
        }
      );
    });

    return () => ctx.revert();
  }, []);

  const splitText = (text: string) =>
    text.split(" ").map((word, i) => (
      <span key={i} className="word inline-block mr-[0.15em]">
        {word}
      </span>
    ));

  return (
    <section
      ref={containerRef}
      className="relative min-h-screen flex items-center px-6 md:px-16 py-24 border-t border-white/5"
    >
      <div className="max-w-7xl mx-auto w-full">
        <div className="grid lg:grid-cols-2 gap-12 lg:gap-24 items-center">
          <h2
            ref={textRef}
            className="font-hero text-[clamp(3rem,8vw,7rem)] leading-[0.9] tracking-tight"
          >
            <div>{splitText("Every business")}</div>
            <div className="text-white/40">{splitText("has a")}</div>
            <div className="text-[#A3FF3F]">{splitText("story.")}</div>
            <div className="text-white/20 text-xl md:text-2xl font-body font-light mt-4 max-w-md">
              {splitText("Most websites fail to tell it.")}
            </div>
          </h2>
          <div className="story-paragraph">
            <p className="text-lg md:text-xl text-[#8B8B8B] leading-relaxed">
              In a digital landscape crowded with templates and trends, your
              brand deserves more than a cookie-cutter presence. We architect
              digital experiences that capture your unique narrative and
              transform casual visitors into loyal customers.
            </p>
            <div className="mt-8 w-16 h-px bg-[#A3FF3F]" />
          </div>
        </div>
      </div>
    </section>
  );
}
