"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export default function ImageReveal() {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        ".reveal-block",
        { scaleY: 1 },
        {
          scaleY: 0,
          duration: 1.2,
          ease: "power3.inOut",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 60%",
            toggleActions: "play none none reverse",
          },
        }
      );

      if (textRef.current) {
        gsap.fromTo(
          textRef.current,
          { y: 60, opacity: 0 },
          {
            y: 0,
            opacity: 1,
            duration: 1,
            delay: 0.3,
            ease: "power3.out",
            scrollTrigger: {
              trigger: containerRef.current,
              start: "top 55%",
              toggleActions: "play none none reverse",
            },
          }
        );
      }
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={containerRef}
      className="relative min-h-screen flex items-center justify-center px-6 md:px-16 py-24 border-t border-white/5 overflow-hidden"
    >
      <div className="relative w-full max-w-6xl mx-auto">
        <div className="relative overflow-hidden rounded-3xl">
          <div className="aspect-video w-full bg-gradient-to-br from-[#A3FF3F]/10 via-[#111111] to-[#090909] border border-white/10" />

          <div className="reveal-block absolute inset-0 bg-[#090909] origin-bottom" />
        </div>

        <h2
          ref={textRef}
          className="font-hero text-[clamp(2.5rem,6vw,6rem)] text-center mt-12 tracking-tight"
        >
          Every pixel
          <br />
          <span className="text-[#A3FF3F]">has a purpose.</span>
        </h2>
      </div>
    </section>
  );
}
