"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const reasons = [
  { title: "Fast", desc: "Lightning-fast load times and optimized performance." },
  { title: "Premium", desc: "Award-caliber design that stands above the rest." },
  { title: "SEO Ready", desc: "Built for search engines from the ground up." },
  { title: "AI Powered", desc: "Cutting-edge AI integration for modern solutions." },
  { title: "Responsive", desc: "Flawless experiences across every device." },
  { title: "Future Proof", desc: "Scalable architecture that grows with you." },
];

export default function WhyChooseUs() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        ".reason-card",
        { y: 80, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.7,
          stagger: 0.08,
          ease: "power3.out",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 75%",
            toggleActions: "play none none reverse",
          },
        }
      );
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={containerRef}
      className="relative px-6 md:px-16 py-24 border-t border-white/5"
    >
      <div className="max-w-7xl mx-auto">
        <span className="text-[11px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          Why Choose Us
        </span>
        <h2 className="font-heading text-4xl md:text-5xl font-bold mt-4 mb-16">
          Built for <span className="text-[#A3FF3F]">excellence</span>
        </h2>

        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
          {reasons.map((reason, i) => (
            <div
              key={i}
              className="reason-card bg-[#111111] border border-white/5 rounded-2xl p-6 md:p-8 hover:border-[#A3FF3F]/30 transition-colors duration-300"
            >
              <div className="font-mono text-xs text-[#A3FF3F] mb-4">
                {String(i + 1).padStart(2, "0")}
              </div>
              <h3 className="font-heading text-2xl font-bold mb-2">
                {reason.title}
              </h3>
              <p className="text-sm text-[#8B8B8B] leading-relaxed">
                {reason.desc}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
