"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const steps = [
  { num: "01", title: "Discover", desc: "We dive deep into your brand, market, and goals." },
  { num: "02", title: "Research", desc: "Data-driven insights shape our strategic direction." },
  { num: "03", title: "Design", desc: "Pixel-perfect interfaces that captivate and convert." },
  { num: "04", title: "Develop", desc: "Clean, performant code brings the vision to life." },
  { num: "05", title: "Launch", desc: "Seamless deployment with zero downtime." },
  { num: "06", title: "Grow", desc: "Continuous optimization drives lasting results." },
];

export default function Process() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        ".step-item",
        { x: -60, opacity: 0 },
        {
          x: 0,
          opacity: 1,
          duration: 0.8,
          stagger: 0.15,
          ease: "power3.out",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 70%",
            toggleActions: "play none none reverse",
          },
        }
      );
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={containerRef}
      className="relative min-h-screen px-6 md:px-16 py-24 border-t border-white/5"
    >
      <div className="max-w-5xl mx-auto">
        <span className="text-[11px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          Our Process
        </span>
        <h2 className="font-heading text-4xl md:text-5xl font-bold mt-4 mb-16">
          How we <span className="text-[#A3FF3F]">build</span>
        </h2>

        <div className="relative">
          <div className="absolute left-8 top-0 bottom-0 w-px bg-white/5 hidden md:block" />

          <div className="space-y-12">
            {steps.map((step, i) => (
              <div key={i} className="step-item relative flex items-start gap-8 md:gap-16">
                <div className="hidden md:flex flex-col items-center">
                  <div className="w-16 h-16 rounded-full border border-white/10 bg-[#090909] flex items-center justify-center z-10">
                    <span className="font-mono text-xs text-[#A3FF3F]">
                      {step.num}
                    </span>
                  </div>
                </div>

                <div className="flex-1 bg-[#111111] rounded-2xl p-6 md:p-8 border border-white/5 hover:border-[#A3FF3F]/20 transition-colors">
                  <div className="flex items-center gap-4 md:hidden mb-2">
                    <span className="font-mono text-xs text-[#A3FF3F]">
                      {step.num}
                    </span>
                  </div>
                  <h3 className="font-hero text-3xl md:text-4xl text-[#F8F8F8]">
                    {step.title}
                  </h3>
                  <p className="mt-2 text-[#8B8B8B]">{step.desc}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
